func init() {
	func() {
		defer func() {
			if r := recover(); r != nil {
				fmt.Fprintln(os.Stderr, "gowt/internal/cocoa: deferred init SWT static{}:", r)
			}
		}()
		BUTTON_MASK = BUTTON1 | BUTTON2 | BUTTON3 | BUTTON4 | BUTTON5
		MODIFIER_MASK = ALT | SHIFT | CTRL | COMMAND | ALT_GR
		var platform string = GetPlatform()
		if "cocoa" == platform {
			MOD1 = COMMAND
			MOD2 = SHIFT
			MOD3 = ALT
			MOD4 = CONTROL
		} else {
			MOD1 = CONTROL
			MOD2 = SHIFT
			MOD3 = ALT
			MOD4 = 0
		}
	}()
}
